import os
for flags,name in [(os.O_RDONLY,'rd'),(os.O_WRONLY,'wr'),(os.O_RDWR,'rdwr'),(os.O_WRONLY|os.O_TRUNC,'wrtr'),(os.O_RDWR|os.O_CREAT|os.O_TRUNC,'create')]:
