{"command": "cd /tmp && python3 -c "
import os
fd=os.open('/tmp/dtest',os.O_RDONLY)
tests=[
 ('copy_file_range', lambda: os.copy_file_range(fd, fd, 10)),
 ('sendfile', lambda: os.sendfile(fd, fd, None, 10)),
 ('splice', lambda: os.splice(fd, fd, 10)),
 ('ftruncate', lambda: os.ftruncate(fd, 0)),
 ('fallocate', lambda: os.posix_fallocate(fd,0,10)),
 ('fadvise', lambda: os.posix_fadvise(fd,0,0,os.POSIX_FADV_SEQUENTIAL)),
 ('fsync', lambda: os.fsync(fd)),
 ('fdatasync', lambda: os.fdatasync(fd)),
 ('fchmod', lambda: os.fchmod(fd,0o644)),
 ('lockf', lambda: os.lockf(fd, os.F_SETLK, 0)),
]
for n,f in tests:
    try: print(n, f())
    except OSError as e: print(n,'err',e.errno,e.strerror)
    except Exception as e: print(n,'other',e)
""}

