{"command": "cd /tmp && python3 -c "
import os,mmap
for p in ['/dev/null','/dev/zero']:
    fd=os.open(p,os.O_RDONLY)
    st=os.fstat(fd); print(p,'size',st.st_size)
    for L in [0,1,4096]:
        try:
            m=mmap.mmap(fd,L,access=mmap.ACCESS_READ); print('  mmap len',L,'ok'); m.close()
        except OSError as e: print('  mmap len',L,'err',e.errno,e.strerror)
    os.close(fd)
""}

