                            out.push(c);
                            // One character too many is consumed.
                            chars.next();
                        }
                        None => {
                            out.push_str("\\u");
                            out.push_str(&digits);
                        }
                    }
                } else {
                    out.push_str("\\u");
                    out.push_str(&digits);
                }
            }
            Some(other) => {
                out.push('\\');
                out.push(other);
            }
            None => out.push('\\'),
        }
    }

    out
}

fn read_file(path: &Path) -> io::Result<Vec<u8>> {
    let file = fs::File::open(path)?;
    let len = file.metadata()?.len();

    let mapped = unsafe { Mapping::new(&file, len) }?;

    Ok(mapped.to_vec())
}

/// A read-only, private, memory mapped view of a file.
unsafe fn mapping_error() -> io::Error {
    io::Error::last_os_error()
}

struct Mapping {
    addr: *mut c_void,
    len: usize,
}

impl Mapping {
    unsafe fn new(file: &fs::File, len: u64) -> io::Result<Mapping> {
        const PROT_READ: i32 = 0x1;
        const MAP_PRIVATE: i32 = 0x02;

        let page_size = page_size();
        let map_len = if len == 0 {
            page_size
        } else {
            len as usize
        };

        let addr = libc_mmap(ptr::null_mut(), map_len, PROT_READ, MAP_PRIVATE, file.as_raw_fd(), 0);
        if addr == usize::MAX as *mut c_void {
            return Err(mapping_error());
        }

        Ok(Mapping { addr, len: map_len })
    }

    fn to_vec(&self) -> Vec<u8> {
        let bytes: &[u8] = unsafe { mem::transmute((self.addr as *const u8, self.len)) };
        bytes.to_vec()
    }
}

impl Drop for Mapping {
    fn drop(&mut self) {
        unsafe {
            libc_munmap(self.addr, self.len);
        }
    }
}

extern "C" {
    fn mmap(
        addr: *mut c_void,
        len: usize,
        prot: i32,
        flags: i32,
        fd: i32,
        offset: i64,
    ) -> *mut c_void;
    fn munmap(addr: *mut c_void, len: usize) -> i32;
    fn sysconf(name: i32) -> i64;
}

fn libc_mmap(
    addr: *mut c_void,
    len: usize,
    prot: i32,
    flags: i32,
    fd: i32,
    offset: i64,
) -> *mut c_void {
    unsafe { mmap(addr, len, prot, flags, fd, offset) }
}

fn libc_munmap(addr: *mut c_void, len: usize) {
    unsafe {
        let _ = munmap(addr, len);
    }
}

const SC_PAGESIZE: i32 = 30;

fn page_size() -> usize {
    let size = unsafe { sysconf(SC_PAGESIZE) };
    if size <= 0 {
        4096
    } else {
        size as usize
    }
}

type WriteError = (PathBuf, io::Error, PathBuf);

fn write_file(path: &Path, content: &[u8]) -> Result<(), WriteError> {
    let canonical = match fs::canonicalize(path) {
        Ok(path) => path,
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    let dir = match canonical.parent() {
        Some(dir) => dir,
        None => Path::new("/"),
    };

    let permissions = match fs::metadata(&canonical) {
        Ok(meta) => meta.permissions(),
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    let tmp = match TempFile::create(dir, permissions) {
        Ok(tmp) => tmp,
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    if let Err(err) = tmp.write(content) {
        let path = tmp.path().to_path_buf();
        tmp.remove();
        return Err((path.to_path_buf(), err, path));
    }

    match fs::rename(tmp.path(), &canonical) {
        Ok(()) => {
            tmp.forget();
            Ok(())
        }
        Err(err) => {
            let tmp_path = tmp.path().to_path_buf();
            tmp.remove();
            Err((path.to_path_buf(), err, tmp_path))
        }
    }
}

struct TempFile {
    path: PathBuf,
    file: Option<fs::File>,
}

impl TempFile {
    fn create(dir: &Path, permissions: fs::Permissions) -> io::Result<TempFile> {
        let mut rng = Rng::new();
        for _ in 0..100 {
            let path = dir.join(format!(".tmp{}", rng.alphanumeric(6)));
            match fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(permissions.mode())
                .open(&path)
