    #[arg(short = 'f', long = "flags", value_name = "FLAGS")]
    flags: Option<String>,

    /// The regexp or string (if using `-F`) to search for
    find: String,

    /// What to replace each match with. Unless in string mode, you may use captured values like
    /// $1, $2, etc
    replace_with: String,

    /// The path to file(s). This is optional - sd can also read from STDIN.
    ///
    /// Note: sd modifies files in-place by default. See documentation for examples.
    files: Vec<PathBuf>,
}

const HELP_TEMPLATE: &str = "\
{before-help}{name} {version}
{about-with-newline}
{usage-heading} {usage}

{all-args}{after-help}";

fn main() {
    let args = Args::parse();

    let flags = Flags::parse(args.flags.as_deref());

    let replacement = if args.fixed_strings {
        // In string-literal mode the replacement is used verbatim: every `$` is escaped so that
        // the regex engine does not try to interpret it as a capture reference.
        Replacement::Literal(args.replace_with.replace('$', "$$"))
    } else {
        Replacement::Captures(unescape(&args.replace_with))
    };

    let pattern = if flags.word && !args.fixed_strings {
        format!("\\b{}\\b", args.find)
    } else {
        args.find.clone()
    };

    let pattern = if args.fixed_strings {
        regex::escape(&pattern)
    } else {
        pattern
    };

    let re = match RegexBuilder::new(&pattern)
        .case_insensitive(flags.case_insensitive)
        .multi_line(flags.multi_line)
        .dot_matches_new_line(flags.dot_matches_new_line)
        .build()
    {
        Ok(re) => re,
        Err(err) => {
            eprintln!("error: invalid regex {err}");
            exit(1);
        }
    };

    if args.files.is_empty() {
        let mut content = Vec::new();
        if let Err(err) = io::stdin().read_to_end(&mut content) {
            eprintln!("error: {err}");
            exit(1);
        }
        let replaced = replace(&re, &content, &replacement, args.max_replacements);
        let stdout = io::stdout();
        let mut out = stdout.lock();
        if let Err(err) = out.write_all(&replaced) {
            eprintln!("error: {err}");
            exit(1);
        }
        return;
    }

    for path in &args.files {
        if !path.exists() {
            eprintln!("error: invalid path: {}", path.display());
            exit(1);
        }
    }

    let mut contents = Vec::with_capacity(args.files.len());
    for path in &args.files {
        match read_file(path) {
            Ok(content) => contents.push(content),
            Err(err) => {
                eprintln!("error: {err}");
                exit(1);
            }
        }
    }

    let results: Vec<Vec<u8>> = contents
        .iter()
        .map(|content| replace(&re, content, &replacement, args.max_replacements))
        .collect();

    if args.preview {
        let stdout = io::stdout();
        let mut out = stdout.lock();
        let multiple = args.files.len() > 1;
        for (path, content) in args.files.iter().zip(results.iter()) {
            if multiple {
                let _ = writeln!(out, "----- FILE {} -----", path.display());
            }
            let _ = out.write_all(content);
        }
        return;
    }

    let mut errors = Vec::new();
    for (path, content) in args.files.iter().zip(results.iter()) {
        if let Err(err) = write_file(path, content) {
            errors.push(err);
        }
    }

    if !errors.is_empty() {
        let mut message = String::from("Failed processing some inputs\n");
        for (path, err, tmp) in errors {
            message.push_str(&format!(
                "    {}: {} at path {:?}\n",
                path.display(),
                err,
                tmp
            ));
        }
        eprintln!("error: {message}");
        exit(1);
    }
}

enum Replacement {
    /// The replacement may contain capture references such as `$1` or `${name}`.
    Captures(String),
    /// The replacement is used as-is.
    Literal(String),
}

fn replace(
    re: &Regex,
    content: &[u8],
    replacement: &Replacement,
    max_replacements: usize,
) -> Vec<u8> {
    match replacement {
        Replacement::Captures(rep) => {
            if max_replacements == 0 {
                re.replace_all(content, rep.as_str()).into_owned()
            } else {
                re.replacen(content, max_replacements, rep.as_str())
                    .into_owned()
            }
        }
        Replacement::Literal(rep) => {
            if max_replacements == 0 {
                re.replace_all(content, NoExpand(rep.as_str())).into_owned()
            } else {
                re.replacen(content, max_replacements, NoExpand(rep.as_str()))
                    .into_owned()
            }
        }
    }
}

struct Flags {
    case_insensitive: bool,
    multi_line: bool,
    dot_matches_new_line: bool,
    word: bool,
}

impl Flags {
    fn parse(flags: Option<&str>) -> Self {
        let mut flags = Self {
            case_insensitive: false,
            multi_line: true,
            dot_matches_new_line: false,
            word: false,
        };

        let Some(spec) = flags else {
            return flags;
        };

        for c in spec.chars() {
            match c {
                'i' => flags.case_insensitive = true,
                'c' => flags.case_insensitive = false,
                's' => flags.dot_matches_new_line = true,
                'w' => {
                    flags.word = true;
                    flags.case_insensitive = false;
                    flags.dot_matches_new_line = false;
                    flags.multi_line = false;
                }
                _ => {}
            }
        }

        if spec.contains('s') {
            flags.multi_line = spec.contains('m');
        }
        if spec.contains('e') || spec.contains('w') {
            flags.multi_line = false;
        }

        flags
    }
}

/// Replaces `\n`, `\t`, `\r`, `\\`, `\xNN` and `\uNNNN` escapes inside of a replacement string.
fn unescape(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut chars = input.chars();

    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }

        match chars.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some('r') => out.push('\r'),
            Some('\\') => out.push('\\'),
            Some('x') => {
                let mut digits = String::new();
                while digits.len() < 2 {
                    match chars.as_str().chars().next() {
                        Some(d) if d.is_ascii_hexdigit() => {
                            digits.push(d);
                            chars.next();
                        }
                        _ => break,
                    }
                }
                if digits.len() == 2 {
                    match u32::from_str_radix(&digits, 16).ok().and_then(char::from_u32) {
                        Some(c) => {
                            out.push(c);
                            // One character too many is consumed.
                            chars.next();
                        }
                        None => {
                            out.push_str("\\x");
                            out.push_str(&digits);
                        }
                    }
                } else {
                    out.push_str("\\x");
                    out.push_str(&digits);
                }
            }
            Some('u') => {
                let mut digits = String::new();
                while digits.len() < 4 {
                    match chars.as_str().chars().next() {
                        Some(d) if d.is_ascii_hexdigit() => {
                            digits.push(d);
                            chars.next();
                        }
                        _ => break,
                    }
                }
                if digits.len() == 4 {
                    match u32::from_str_radix(&digits, 16).ok().and_then(char::from_u32) {
                        Some(c) => {
                            out.push(c);
                            // One character too many is consumed.
                            chars.next();
                        }
                        None => {
                            out.push_str("\\u");
                            out.push_str(&digits);
                        }
                    }
                } else {
                    out.push_str("\\u");
                    out.push_str(&digits);
                }
            }
            Some(other) => {
                out.push('\\');
                out.push(other);
            }
            None => out.push('\\'),
        }
    }

    out
}

fn read_file(path: &Path) -> io::Result<Vec<u8>> {
    let file = fs::File::open(path)?;
    let len = file.metadata()?.len();

    let mapped = unsafe { Mapping::new(&file, len) }?;

    Ok(mapped.to_vec())
}

/// A read-only, private, memory mapped view of a file.
unsafe fn mapping_error() -> io::Error {
    io::Error::last_os_error()
}

struct Mapping {
    addr: *mut c_void,
    len: usize,
}

impl Mapping {
    unsafe fn new(file: &fs::File, len: u64) -> io::Result<Mapping> {
        const PROT_READ: i32 = 0x1;
        const MAP_PRIVATE: i32 = 0x02;

        let page_size = page_size();
        let map_len = if len == 0 {
            page_size
        } else {
            len as usize
        };

        let addr = libc_mmap(ptr::null_mut(), map_len, PROT_READ, MAP_PRIVATE, file.as_raw_fd(), 0);
        if addr == usize::MAX as *mut c_void {
            return Err(mapping_error());
        }

        Ok(Mapping { addr, len: map_len })
    }

    fn to_vec(&self) -> Vec<u8> {
        let bytes: &[u8] = unsafe { mem::transmute((self.addr as *const u8, self.len)) };
        bytes.to_vec()
    }
}

impl Drop for Mapping {
    fn drop(&mut self) {
        unsafe {
            libc_munmap(self.addr, self.len);
        }
    }
}

extern "C" {
    fn mmap(
        addr: *mut c_void,
        len: usize,
        prot: i32,
        flags: i32,
        fd: i32,
        offset: i64,
    ) -> *mut c_void;
    fn munmap(addr: *mut c_void, len: usize) -> i32;
    fn sysconf(name: i32) -> i64;
}

fn libc_mmap(
    addr: *mut c_void,
    len: usize,
    prot: i32,
    flags: i32,
    fd: i32,
    offset: i64,
) -> *mut c_void {
    unsafe { mmap(addr, len, prot, flags, fd, offset) }
}

fn libc_munmap(addr: *mut c_void, len: usize) {
    unsafe {
        let _ = munmap(addr, len);
    }
}

const SC_PAGESIZE: i32 = 30;

fn page_size() -> usize {
    let size = unsafe { sysconf(SC_PAGESIZE) };
    if size <= 0 {
        4096
    } else {
        size as usize
    }
}

type WriteError = (PathBuf, io::Error, PathBuf);

fn write_file(path: &Path, content: &[u8]) -> Result<(), WriteError> {
    let canonical = match fs::canonicalize(path) {
        Ok(path) => path,
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    let dir = match canonical.parent() {
        Some(dir) => dir,
        None => Path::new("/"),
    };

    let permissions = match fs::metadata(&canonical) {
        Ok(meta) => meta.permissions(),
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    let tmp = match TempFile::create(dir, permissions) {
        Ok(tmp) => tmp,
        Err(err) => return Err((path.to_path_buf(), err, PathBuf::new())),
    };

    if let Err(err) = tmp.write(content) {
        let path = tmp.path().to_path_buf();
        tmp.remove();
        return Err((path.to_path_buf(), err, path));
    }

    match fs::rename(tmp.path(), &canonical) {
        Ok(()) => {
            tmp.forget();
            Ok(())
        }
        Err(err) => {
            let tmp_path = tmp.path().to_path_buf();
            tmp.remove();
            Err((path.to_path_buf(), err, tmp_path))
        }
    }
}

struct TempFile {
    path: PathBuf,
    file: Option<fs::File>,
}

impl TempFile {
    fn create(dir: &Path, permissions: fs::Permissions) -> io::Result<TempFile> {
        let mut rng = Rng::new();
        for _ in 0..100 {
            let path = dir.join(format!(".tmp{}", rng.alphanumeric(6)));
            match fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(permissions.mode())
                .open(&path)
            {
                Ok(file) => {
                    return Ok(TempFile {
                        path,
                        file: Some(file),
                    })
                }
                Err(err) if err.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(err) => return Err(err),
            }
        }

        Err(io::Error::new(
            io::ErrorKind::AlreadyExists,
            "too many temporary files exist",
        ))
    }

    fn path(&self) -> &Path {
        &self.path
    }

    fn write(&self, content: &[u8]) -> io::Result<()> {
        let mut file = self.file.as_ref().unwrap().try_clone()?;
        file.write_all(content)
    }

    fn remove(&self) {
        let _ = fs::remove_file(&self.path);
    }

    fn forget(mut self) {
        self.file = None;
    }
}

struct Rng([u8; 32]);

impl Rng {
    fn new() -> Rng {
        let mut seed = [0u8; 32];
        if let Ok(mut f) = fs::File::open("/dev/urandom") {
            if f.read_exact(&mut seed).is_ok() {
                return Rng(seed);
            }
        }

        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0) as u64;
        let pid = std::process::id() as u64;
        let mut state = nanos ^ (pid << 32) ^ 0x9E37_79B9_7F4A_7C15;
        for byte in seed.iter_mut() {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            *byte = state as u8;
        }

        Rng(seed)
    }

    fn alphanumeric(&mut self, len: usize) -> String {
        const CHARSET: &[u8] = b"0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
        let mut out = String::with_capacity(len);
        for i in 0..len {
            let byte = self.0[i % self.0.len()];
            out.push(CHARSET[byte as usize % CHARSET.len()] as char);
        }
        out
    }
}
