#!/usr/bin/env python3
import os, subprocess, shutil, sys, tempfile

ORIG = "/workspace/executable"
MINE = "/tmp/mysd"

def run(exe, args, stdin=b"", setup=None, cwd=None):
    """setup: callable(dir) creating files; returns (stdout, stderr, rc, tree)"""
    d = tempfile.mkdtemp(dir="/tmp/harness")
    if setup: setup(d)
    p = subprocess.run([exe]+args, input=stdin, capture_output=True, cwd=d)
    tree = []
    for root, dirs, files in os.walk(d):
        dirs.sort(); files.sort()
        rel = os.path.relpath(root, d)
        for f in files:
            fp = os.path.join(root,f)
            try:
                data = open(fp,'rb').read()
            except Exception as e:
                data = b"<unreadable>"
            mode = oct(os.stat(fp).st_mode & 0o777)
            tree.append((os.path.normpath(os.path.join(rel,f)), data, mode))
    tree.sort()
    shutil.rmtree(d, ignore_errors=True)
    return p.stdout, p.stderr, p.returncode, tree

def cmp_case(name, args, stdin=b"", setup=None, replace_tmp=True, stdout_has_tmp=False):
    o = run(ORIG, args, stdin, setup)
    m = run(MINE, args, stdin, setup)
    def norm(res):
        out, err, rc, tree = res
        out = out.replace(ORIG.encode(), b"<EXE>").replace(MINE.encode(), b"<EXE>")
        err = err.replace(ORIG.encode(), b"<EXE>").replace(MINE.encode(), b"<EXE>")
        if replace_tmp:
            import re
            err = re.sub(rb'\.tmp[0-9A-Za-z]{6}', b'.tmpXXXXXX', err)
        return (out, err, rc, tree)
    no, nm = norm(o), norm(m)
    if no == nm:
        return True
    print("=== MISMATCH:", name, args)
    for i, lbl in enumerate(["stdout","stderr","rc","tree"]):
        if no[i] != nm[i]:
            print("  orig %s: %r" % (lbl, no[i]))
            print("  mine %s: %r" % (lbl, nm[i]))
    return False

if __name__ == "__main__":
    cases = []
    print("pass")
