#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flags_default_to_multi_line_matching() {
        let flags = Flags::parse(None);
        assert!(flags.multi_line);
        assert!(!flags.case_insensitive);
        assert!(!flags.dot_matches_new_line);
        assert!(!flags.word);
    }

    #[test]
    fn flags_disable_multi_line() {
        for spec in ["e", "w", "s", "em", "me", "mw", "wm", "is", "si"] {
            assert!(!Flags::parse(Some(spec)).multi_line, "{spec}");
        }

        for spec in ["", "m", "i", "c", "a", "ms", "sm", "msi", "sms"] {
            assert!(Flags::parse(Some(spec)).multi_line, "{spec}");
        }
    }

    #[test]
    fn flags_last_case_sensitive_wins() {
        assert!(Flags::parse(Some("i")).case_insensitive);
        assert!(!Flags::parse(Some("c")).case_insensitive);
        assert!(Flags::parse(Some("ci")).case_insensitive);
        assert!(!Flags::parse(Some("ic")).case_insensitive);
        // `w` resets case-insensitivity, no matter where it shows up.
        assert!(!Flags::parse(Some("iw")).case_insensitive);
        assert!(Flags::parse(Some("wi")).case_insensitive);
    }

    #[test]
    fn flags_last_dot_matches_new_line_wins() {
        assert!(!Flags::parse(Some("s")).dot_matches_new_line);
        assert!(Flags::parse(Some("s")).multi_line == false);
        assert!(Flags::parse(Some("ws")).dot_matches_new_line);
        assert!(!Flags::parse(Some("sw")).dot_matches_new_line);
    }

    #[test]
    fn unescape_expands_known_escapes() {
        assert_eq!(unescape("\\n"), "\n");
        assert_eq!(unescape("\\t"), "\t");
        assert_eq!(unescape("\\r"), "\r");
        assert_eq!(unescape("\\\\"), "\\");
        assert_eq!(unescape("\\'"), "'");
        assert_eq!(unescape("\\\""), "\"");
    }

    #[test]
    fn unescape_leaves_unknown_escapes_alone() {
        assert_eq!(unescape("\\q"), "\\q");
        assert_eq!(unescape("\\0"), "\\0");
        assert_eq!(unescape("\\x4G"), "\\x4G");
        assert_eq!(unescape("\\u004G"), "\\u004G");
        assert_eq!(unescape("\\u{41}"), "\\u{41}");
        assert_eq!(unescape("\\"), "\\");
    }

    #[test]
    fn unescape_expands_hex_and_unicode_escapes() {
        assert_eq!(unescape("\\x41"), "A");
        assert_eq!(unescape("\\x4A"), "J");
        assert_eq!(unescape("\\xff"), "\u{ff}");
        assert_eq!(unescape("\\u00e9"), "\u{e9}");
        assert_eq!(unescape("\\uFFFF"), "\u{ffff}");
        // Surrogate code points are not valid scalars and stay untouched.
        assert_eq!(unescape("\\uD800"), "\\uD800");
    }

    #[test]
    fn unescape_consumes_one_extra_character() {
        // The original consumes a single character more than it should after `\x` and
        // `\u` escapes; the behaviour is kept as is.
        assert_eq!(unescape("\\x241"), "$");
        assert_eq!(unescape("\\x24 1"), "$1");
        assert_eq!(unescape("\\x24ab"), "$b");
        assert_eq!(unescape("\\u0041b"), "A");
        assert_eq!(unescape("\\x41\\x41"), "Ax41");
        assert_eq!(unescape("\\x24"), "$");
        assert_eq!(unescape("\\x24$1"), "$1");
        assert_eq!(unescape("\\x24z"), "$");
    }

    #[test]
    fn word_flag_wraps_the_pattern() {
        // The pattern is wrapped in word boundaries without any grouping.
        let re = RegexBuilder::new("\\b(\\w+)\\b").build().unwrap();
        assert!(re.is_match(b"word"));
    }

    #[test]
    fn replacement_limit_is_respected() {
        let re = RegexBuilder::new("a").build().unwrap();
        let replacement = Replacement::Captures("X".to_string());

        assert_eq!(replace(&re, b"aaaa", &replacement, 0), &b"XXXX"[..]);
        assert_eq!(replace(&re, b"aaaa", &replacement, 1), &b"Xaaa"[..]);
        assert_eq!(replace(&re, b"aaaa", &replacement, 10), &b"XXXX"[..]);
    }

    #[test]
    fn literal_replacement_ignores_capture_references() {
        let re = RegexBuilder::new("a").build().unwrap();
        let replacement = Replacement::Literal("$1".to_string());

        assert_eq!(
            replace(&re, b"aaa", &replacement, 0),
            &b"$1$1$1"[..]
        );
    }
}
