//! A tiny implementation of the terminal size query that the `clap` help formatter uses.
//!
//! The public API mirrors the `terminal_size` crate that `clap` optionally depends on:
//! `terminal_size()` reports the size of the terminal attached to stdout, stderr or stdin.

use std::mem::zeroed;
use std::os::unix::io::AsRawFd;

/// The width of a terminal, in characters.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct Width(pub u16);

/// The height of a terminal, in characters.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Copy, Clone, Debug)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

/// Returns the size of the terminal that is attached to stdout, stderr or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    if let Some(size) = terminal_size_of(std::io::stdout()) {
        return Some(size);
    }

    if let Some(size) = terminal_size_of(std::io::stderr()) {
        return Some(size);
    }

    if let Some(size) = terminal_size_of(std::io::stdin()) {
        return Some(size);
    }

    None
}

/// Returns the size of the terminal that the given file descriptor points to.
pub fn terminal_size_of<F: AsRawFd>(fd: F) -> Option<(Width, Height)> {
    let mut winsize: Winsize = unsafe { zeroed() };

    let result = unsafe { ioctl(fd.as_raw_fd(), TIOCGWINSZ, &mut winsize as *mut Winsize) };
    if result == -1 {
        return None;
    }

    if winsize.ws_row > 0 && winsize.ws_col > 0 {
        Some((Width(winsize.ws_col), Height(winsize.ws_row)))
    } else {
        None
    }
}
EOF
